/* What a lifting recomp needs to see: the module's entry points, the hook table
   and its slots (docs/exefs.md, "Lifting"). Everything else stays local. */
{
  global:
    _init;
    coop_frame_entry;
    coop_proto_frame;
    coop_hooks;
    coop_slot_*;
    coop_call_*;
  local: *;
};
